CREATE TABLE IF NOT EXISTS payments (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,payment_id VARCHAR(36) NOT NULL,idempotency_key VARCHAR(150) NOT NULL,order_id VARCHAR(80) NOT NULL,amount DECIMAL(19,2) NOT NULL,currency VARCHAR(3) NOT NULL,payment_status VARCHAR(30) NOT NULL,CONSTRAINT uk_payments_idempotency_key UNIQUE(idempotency_key));